mapper.select:
SELECT r.id, r.message_id, r.user_id, u.username AS user_account, u.real_name AS user_name, m.connection_id, m.platform, m.title, m.content AS message_content, r.delivery_status, r.delivery_attempts, r.external_id, r.last_error_code, r.last_attempt_time, r.next_retry_time, r.create_time FROM sys_message_receiver r INNER JOIN sys_message m ON m.id = r.message_id AND m.tenant_id = r.tenant_id LEFT JOIN sys_user u ON u.id = r.user_id WHERE r.tenant_id = #{tenantId} AND m.send_channel = 'COLLABORATION' AND r.delivery_status IS NOT NULL
AND m.connection_id = #{connectionId}
AND m.platform = #{platform}
AND r.delivery_status = #{deliveryStatus}
AND r.message_id = #{messageId}
ORDER BY r.id DESC

mapper.update:
UPDATE sys_message_receiver
SET delivery_status = #{deliveryStatus},
    delivery_attempts = COALESCE(delivery_attempts, 0) + 1,
    external_id = #{externalId},
    last_error_code = #{lastErrorCode},
    last_attempt_time = #{lastAttemptTime},
    next_retry_time = #{nextRetryTime}
WHERE id = #{id}
  AND tenant_id = #{tenantId}
